        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      router.refresh();
      router.replace("/dashboard");
    } catch (e) {
      const err = e as AuthError;
      setError(mapFirebaseError(err));
    } finally {
      setPending(null);
    }
  }

